/**
 * @summary Submit contact form
 */
export const getSubmitContactUrl = () => {
  return `/api/contact`;
};

export const submitContact = async (
  contactRequest: ContactRequest,
  options?: RequestInit,
): Promise<SuccessResponse> => {
  return customFetch<SuccessResponse>(getSubmitContactUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(contactRequest),
  });
};

export const getSubmitContactMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof submitContact>>,
    TError,
    { data: BodyType<ContactRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof submitContact>>,
  TError,
  { data: BodyType<ContactRequest> },
  TContext
> => {
  const mutationKey = ["submitContact"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof submitContact>>,
    { data: BodyType<ContactRequest> }
  > = (props) => {
    const { data } = props ?? {};

    return submitContact(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

